 static void writeOverlayZip(Path zip,String name)throws Exception{try(java.util.zip.ZipOutputStream out=new java.util.zip.ZipOutputStream(Files.newOutputStream(zip))){writeZipEntry(out,"manifest.json","{\"format\":1,\"spec\":\"0.3\",\"id\":\"test:zip_overlay\",\"name\":\""+name+"\",\"requires\":[],\"optional\":[]}");writeZipEntry(out,"pipeline.json","{\"format\":1,\"passes\":[]}");}}
 static void writeZipEntry(java.util.zip.ZipOutputStream out,String name,String text)throws Exception{java.util.zip.ZipEntry e=new java.util.zip.ZipEntry(name);e.setTime(0L);out.putNextEntry(e);out.write(text.getBytes(java.nio.charset.StandardCharsets.UTF_8));out.closeEntry();}
 static boolean hasPlatformFrameSource(String diagnostics){return diagnostics.matches(".*platformFrame=\\{validated=[1-9][0-9]* epoch=[0-9]+ sequence=[0-9]+ sources=[1-9][0-9]*\\}.*");}
 static boolean hasPlatformFrameMotion(String diagnostics){return diagnostics.matches(".*platformMotion=\\{movingSources=[1-9][0-9]*\\}.*");}
 static boolean sourceFrameRefreshBalanced(String diagnostics){java.util.regex.Matcher m=java.util.regex.Pattern.compile("sourceFrameRefresh=\\{requested=([0-9]+) scheduled=([0-9]+)\\}").matcher(diagnostics);return m.find()&&m.group(1).equals(m.group(2));}
